# Quiz 5 text and direct solver links; loaded only when selected.
import STCORE as c

EXAMPLES=(
 ('QZ501 CREDIT CARDS','NOT BINOMIAL. ENTER X/P(X): 0/.07, 1/.68, 2/.21, 3/.03, 4/.01. MEAN=SUM(xP)=1.2300. VARIANCE=.4371; SD=.6611. AT MOST 2: P(X<=2)=.9600. AT LEAST 3: P(X>=3)=.0400. USE THE TABLE SOLVER AND REUSE ROWS FOR ALL PARTS. DISTRIBUTION SD IS NOT SAMPLE SD.'),
 ('QZ502 GIRLS / ROUNDED TABLE','0 THROUGH 14 IS 15 POSSIBLE VALUES, NOT 14. THE PRINTED TABLE SUMS TO .999 AND HAS ROUNDED ZEROS. USE ROUNDED TABLE MODE FOR APPROXIMATE SUMS; DO NOT NORMALIZE IT SILENTLY. WITHOUT THE TABLE, ASSUME INDEPENDENT BIRTHS WITH p(GIRL)=.5: BINOMIAL n=14,p=.5. P(X=10)=binompdf(14,.5,10)=.0611. P(X<=4)=binomcdf(14,.5,4)=.0898. P(X>=10)=1-binomcdf(14,.5,9)=.0898. P(X>=12)=1-binomcdf(14,.5,11)=.0065. THE ROUNDED TABLE SUM FOR X>=12 IS .007. MODEL MEAN=7; SD=SQRT(3.5)=1.8708. AT MOST 4 IS NOT UNUSUAL AT .05: .0898>.05. USE THE ENTIRE LOWER TAIL, NOT P(X=4).'),
 ('QZ503 DIE GAME / NET VALUE','PAY $2; GROSS PRIZE $4 FOR FACE 2 OR 3, OTHERWISE $0. NET OUTCOMES +$2 WITH CHANCE 2/6 AND -$2 WITH CHANCE 4/6. E=(2)(2/6)+(-2)(4/6)=-2/3=-$.67. PLAYER LOSES ABOUT 67 CENTS PER PLAY LONG RUN. PAYOFF ENTRY: COST 2, PRIZES 4 AND 0, WEIGHTS 2 AND 4. IF ENTERING NET OUTCOMES INSTEAD, COST MUST BE 0. DO NOT SUBTRACT COST TWICE.'),
 ('QZ504 METRA / LOWER TAIL','BINOMIAL n=60,p=.74. P(X<=38)=binomcdf(60,.74,38)=.0447. BINOMIAL MENU 2 AT MOST. RESULT MENU 6 CHECKS UNUSUAL EVENT WITH DEFAULT CUTOFF .05. .0447<=.05: EVIDENCE AGAINST THE CLAIMED RATE IN THE DIRECTION OF A LOWER ON-TIME RATE, ASSUMING THE MODEL. NOT PROOF THE CLAIM IS FALSE.'),
 ('QZ505 PACKAGING / TWO RULES','BINOMIAL n=700,p=.68. MEAN=476; SD=12.3418. MIN USUAL=451.3164; MAX USUAL=500.6836. 521 IS UNUSUALLY HIGH UNDER THE STRICT TWO-SD RULE. BINOMIAL MENU 8 MEAN/SD/USUAL, CHECK 521. THEN CHOOSE AT LEAST WITH SAME n,p: P(X>=521)=1-binomcdf(700,.68,520)=.0001200177, ROUNDED .0001. TWO-SD CLASSIFICATION AND A PROBABILITY CUTOFF ARE DISTINCT CRITERIA. DO NOT SUBSTITUTE P(X=521) FOR THE UPPER TAIL.'))


def quiz_menu():
    while True:
        key=c.menu('QUIZ 5 / DISTRIBUTIONS',[(str(i+1),title) for i,(title,body) in enumerate(EXAMPLES)]+[('6','OPEN EXACT X/P TABLE'),('7','OPEN ROUNDED X/P TABLE'),('8','OPEN BINOMIAL WORDS'),('9','OPEN GAME PAYOFF TABLE')])
        if key=='0': return
        if int(key)<=5:
            title,body=EXAMPLES[int(key)-1]
            c.call('STSTUDY','definition_pages',title,body)
        else: c.call(*{'6':('STCOUNT','distribution_session'),'7':('STCOUNT','rounded_distribution_session'),'8':('STBWORD','wording_session'),'9':('STCOUNT','payoff_session')}[key])
